char * ssh_connection_hash ( const char * thishost , const char * host , const char * portstr , const char * user ) { struct ssh_digest_ctx * md ; u_char conn_hash [ SSH_DIGEST_MAX_LENGTH ] ; if ( ( md = ssh_digest_start ( SSH_DIGEST_SHA1 ) ) == NULL || ssh_digest_update ( md , thishost , strlen ( thishost ) ) < 0 || ssh_digest_update ( md , host , strlen ( host ) ) < 0 || ssh_digest_update ( md , portstr , strlen ( portstr ) ) < 0 || ssh_digest_update ( md , user , strlen ( user ) ) < 0 || ssh_digest_final ( md , conn_hash , sizeof ( conn_hash ) ) < 0 ) { fatal_f ( "mux digest failed" ) ; } return tohex ( conn_hash , ssh_digest_bytes ( SSH_DIGEST_SHA1 ) ) ; } 